sources.sql:
physical SQLite table: "category"
CREATE TABLE "category" (
  "category_id" SMALLINT -- PRIMARY KEY
  "name" VARCHAR(25)
  "last_update" TIMESTAMP
);

physical SQLite table: "country"
CREATE TABLE "country" (
  "country_id" SMALLINT -- PRIMARY KEY
  "country" VARCHAR(50)
  "last_update" TIMESTAMP
);

physical SQLite table: "film_actor"
CREATE TABLE "film_actor" (
  "actor_id" INT -- PRIMARY KEY; REFERENCES "actor"("actor_id")
  "film_id" INT -- PRIMARY KEY; REFERENCES "film"("film_id")
  "last_update" TIMESTAMP
);

physical SQLite table: "film_category"
CREATE TABLE "film_category" (
  "film_id" INT -- PRIMARY KEY; REFERENCES "film"("film_id")
  "category_id" SMALLINT -- PRIMARY KEY; REFERENCES "category"("category_id")
  "last_update" TIMESTAMP
);

physical SQLite table: "film_text"
CREATE TABLE "film_text" (
  "film_id" SMALLINT -- PRIMARY KEY
  "title" VARCHAR(255)
  "description" BLOB SUB_TYPE TEXT
);

physical SQLite table: "language"
CREATE TABLE "language" (
  "language_id" SMALLINT -- PRIMARY KEY
  "name" CHAR(20)
  "last_update" TIMESTAMP
);

